class Solution:
    def sumOfGoodNumbers(self, nums: List[int], k: int) -> int:
        total = 0
        n = len(nums)
        for i in range(n):
            # Check if the element at index i is good
            # It needs to be strictly greater than elements at i-k and i+k (if they exist)
            is_good = True
            # Check left neighbor (i - k)
            if i - k >= 0:
                if nums[i] <= nums[i - k]:
                    is_good = False
            # Check right neighbor (i + k)
            if is_good and i + k < n:
                if nums[i] <= nums[i + k]:
                    is_good = False
            if is_good:
                total += nums[i]
        return total
