class Solution:
    def findValidPair(self, s: str) -> str:
        # Count frequency of each digit
        from collections import Counter
        freq = Counter(s)

        # Traverse the string to find the first valid pair
        for i in range(len(s) - 1):
            d1, d2 = s[i], s[i+1]
            # Check if the two digits are different
            if d1 != d2:
                # Check if each digit appears exactly as many times as its numeric value
                if freq[d1] == int(d1) and freq[d2] == int(d2):
                    return d1 + d2

        return ""
